  scenes.push({title:'What could change it?',caption:fact?(fact.horse?title(fact.horse)+': ':'')+fact.summary:'Track, pace and final runner changes still matter.',narration:fact&&words(fact.summary)+(fact.horse?words(fact.horse):0)<=17?(fact.horse?title(fact.horse)+'. ':'')+fact.summary:'Track, pace and final runner changes still matter.',source:fact?.url});
